// pncp_id no formato numeroControlePNCP: {cnpj}-{tipo}-{sequencial}/{ano}
// (ex: "07251534000130-1-000071/2026") -- carrega tudo que precisamos sem
// depender de um link salvo (licitacoes_resumos nao guarda link).
const item = $input.first().json;
const m = String(item.pncp_id || '').match(/^(\d{14})-\d+-(\d+)\/(\d{4})$/);
return [{ json: { ...item,
  cnpj: m ? m[1] : null,
  sequencial: m ? String(parseInt(m[2], 10)) : null,
  ano: m ? m[3] : null
} }];

// Descoberta desta sessao: o PNCP tem um endpoint de METADADOS dos anexos
// (titulo/tipoDocumentoDescricao reais), bem melhor que baixar arquivo_id as
// cegas (jeito que o Resumidor -- Passo 3 -- ainda usa). Aqui da pra achar a
// minuta de contrato pelo TITULO antes de baixar qualquer coisa.
// Resposta do PNCP e um array JSON no nivel raiz. O node httpRequest do n8n
// PODE quebrar isso em 1 item por elemento (comportamento padrao documentado
// pra respostas JSON array) OU vir como 1 item so contendo o array -- trata os
// dois formatos pra nao depender de suposicao nao validada ao vivo ainda.
function normalizar(s) {
  return String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}
const base = $('Extrair CNPJ Ano Sequencial Contrato').first().json;
const rawItems = $input.all().map(i => i.json);
let arquivos;
if (rawItems.length === 1 && Array.isArray(rawItems[0])) {
  arquivos = rawItems[0];
} else {
  arquivos = rawItems.filter(a => a && a.sequencialDocumento != null);
}
// BUG REAL encontrado buscando um edital real com minuta pra testar: orgaos
// publicos frequentemente titulam o anexo "MODELO DE CONTRATO" em vez de
// "MINUTA DE CONTRATO" (ex real achado ao vivo: "MODELO CONTRATO AQUISICAO DE
// MOBILIARIOS - PREGAO.pdf") -- so procurar "minuta" deixava esse caso passar
// batido. Agora aceita minuta OU modelo, sempre exigindo a palavra contrato/ata
// junto (pra nao confundir com "Modelo de Proposta", que e outro anexo comum).
const minuta = arquivos.find(a => {
  const t = normalizar(a.titulo) + ' ' + normalizar(a.tipoDocumentoDescricao);
  return (t.includes('minuta') || t.includes('modelo')) && (t.includes('contrato') || t.includes('ata'));
}) || arquivos.find(a => normalizar(a.titulo).includes('minuta'));
return [{ json: { ...base,
  minuta_encontrada: !!minuta,
  minuta_sequencial: minuta ? minuta.sequencialDocumento : null,
  minuta_titulo: minuta ? minuta.titulo : null
} }];

const item = $input.first().json;
const texto = item.text || '';
return [{ json: { ...($('Encontrar Minuta').first().json), texto_minuta: texto } }];

// Buscar Dados Empresa/Buscar Valor Proposta podem devolver 0 linhas -- trata
// com placeholders claros, nunca inventa dado (mesmo padrao do Redator de
// Propostas). Valor NUNCA e decidido aqui -- so repassa o que ja foi
// registrado por um humano em licitacoes_propostas.valor_ofertado.
const proposta = $input.first().json || {};
const empresa = $('Buscar Dados Empresa Contrato').first().json || {};
const usuario = $('Buscar Usuario Contrato').first().json || {};
const base = $('Marcar Texto Minuta').first().json;
return [{ json: {
  resumo_id: base.resumo_id,
  perfil_id: base.perfil_id || null,
  usuario_id: $('Extrair Corpo Contrato').first().json.usuario_id,
  whatsapp_numero: usuario.whatsapp_numero,
  texto_minuta: base.texto_minuta,
  razao_social: empresa.razao_social || '[RAZAO SOCIAL A PREENCHER]',
  cnpj: empresa.cnpj || '[CNPJ A PREENCHER]',
  endereco: empresa.endereco || '[ENDERECO A PREENCHER]',
  responsavel_legal: empresa.responsavel_legal || '[RESPONSAVEL LEGAL A PREENCHER]',
  objeto_resumo: base.objeto_resumo,
  prazo_entrega: base.prazo_entrega,
  valor_ofertado: proposta.valor_ofertado != null ? proposta.valor_ofertado : null
} }];

const aiOutput = $input.first().json;
const texto = (aiOutput.message && aiOutput.message.content) || '';
const ctx = $('Montar Contexto Contrato').first().json;
return [{ json: { ...ctx, conteudo_contrato: texto } }];

