const ctx = $('Extrair Texto Contrato').first().json;
const texto = '📄 RASCUNHO DE CONTRATO -- revise antes de qualquer assinatura. A IA preencheu os campos variaveis da minuta oficial do edital, mas isso NAO e um documento final.\n\n' + ctx.conteudo_contrato;
return [{ json: { numero: (ctx.whatsapp_numero || '').replace(/\D/g, ''), texto } }];

const usuario = $input.first().json || {};
if (!usuario.whatsapp_numero) return [];
const texto = '📄 Nao encontrei uma minuta de contrato oficial entre os anexos deste edital. Nao vou redigir um contrato do zero -- se voce tiver o modelo em maos, me manda que eu preencho, ou fale com o orgao responsavel pra obter a minuta oficial.';
return [{ json: { numero: usuario.whatsapp_numero.replace(/\D/g, ''), texto } }];
